    Lesson(
      id: 'e8_l9',
      courseId: 'eng_8',
      title: 'Grammar: Voice Change',
      durationMinutes: 20,
      orderIndex: 8,
      content: 'Voice shows whether the subject does the work or the work is done to the subject.\n\nActive Voice: The subject is active (does the work).\nExample: I eat rice.\n\nPassive Voice: The subject is passive (receives the action).\nExample: Rice is eaten by me.\n\nRules for changing Active to Passive:\n1. The object becomes the subject.\n2. An auxiliary verb (am/is/are/was/were) is added based on tense.\n3. The main verb is changed to its Past Participle (V3) form.\n4. "By" is added before the new object (the old subject).',
      quizzes: [
        Quiz(id: 'e8_l9_q1', courseId: 'eng_8', question: 'In Active Voice, the subject...', options: ['Does the work', 'Receives the action', 'Is hidden', 'Is not important'], correctIndex: 0),
        Quiz(id: 'e8_l9_q2', courseId: 'eng_8', question: 'In Passive Voice, the subject...', options: ['Does the work', 'Receives the action', 'Is always "I"', 'Is always a person'], correctIndex: 1),
        Quiz(id: 'e8_l9_q3', courseId: 'eng_8', question: 'Which is an active sentence?', options: ['The ball was thrown', 'I eat rice', 'Rice is eaten by me', 'The car was washed'], correctIndex: 1),
        Quiz(id: 'e8_l9_q4', courseId: 'eng_8', question: 'Which is a passive sentence?', options: ['He plays cricket', 'Cricket is played by him', 'She sings a song', 'They build a house'], correctIndex: 1),
        Quiz(id: 'e8_l9_q5', courseId: 'eng_8', question: 'When changing from active to passive, the object becomes the...', options: ['Verb', 'Subject', 'Adverb', 'Preposition'], correctIndex: 1),
        Quiz(id: 'e8_l9_q6', courseId: 'eng_8', question: 'In passive voice, the main verb is ALWAYS in which form?', options: ['Present (V1)', 'Past (V2)', 'Past Participle (V3)', 'ing-form'], correctIndex: 2),
        Quiz(id: 'e8_l9_q7', courseId: 'eng_8', question: 'What preposition is usually used before the object in passive voice?', options: ['In', 'At', 'By', 'On'], correctIndex: 2),
        Quiz(id: 'e8_l9_q8', courseId: 'eng_8', question: 'Active: "I see a bird." Passive: ?', options: ['A bird is saw by me.', 'A bird is seen by me.', 'A bird was seen by me.', 'A bird is see by me.'], correctIndex: 1),
        Quiz(id: 'e8_l9_q9', courseId: 'eng_8', question: 'Active: "He wrote a letter." Passive: ?', options: ['A letter is written by him.', 'A letter was wrote by him.', 'A letter was written by him.', 'A letter has written by him.'], correctIndex: 2),
